<script setup lang="ts">import{computed,inject,watch}from'vue';import{useAppStore}from'../app/store';import{useModuleStore}from'../app/moduleStore';import{useToastStore}from'../app/toastStore';import type{ModuleClient}from'../bridge/clients/ModuleClient';import QPage from'../design-system/components/QPage.vue';import QEmptyState from'../design-system/components/QEmptyState.vue';const app=useAppStore();const modules=useModuleStore();const toast=useToastStore();const client=inject<ModuleClient>('moduleClient')!;async function refresh(){modules.begin();try{modules.complete(await client.getSnapshot());toast.show('Module snapshot refreshed.','success')}catch(e){modules.fail(e);toast.show('The host could not refresh modules.','error')}}watch(()=>app.bridge,bridge=>{if(bridge==='Connected'&&modules.status==='idle')void refresh()},{immediate:true});const running=computed(()=>modules.modules.filter(x=>x.runtimeState==='Running').length);const loaded=computed(()=>modules.modules.filter(x=>x.runtimeState==='Loaded').length);const failed=computed(()=>modules.modules.filter(x=>x.errorCount>0||!x.isValid).length)</script>
<template><QPage class="home-page"><QEmptyState v-if="modules.status==='ready'&&modules.modules.length===0" title="Your toolbox is empty" description="Modules you add will appear here without being loaded automatically."/><template v-else><section class="wpf-home-hero"><div><small>System status</small><h1>Running normally <span>✓</span></h1><p>All discovered modules are shown from the authoritative host state.</p><RouterLink class="q-button wpf-light-button" to="/modules">View modules</RouterLink></div><div class="wpf-hero-icon">▦</div></section><section class="wpf-home-summary"><article><label>Installed modules</label><strong>{{modules.modules.length}}</strong></article><article><label>Running modules</label><strong class="success">{{running}}</strong></article><article><label>Loaded modules</label><strong class="accent">{{loaded}}</strong></article><article><label>Issues</label><strong class="warning">{{failed}}</strong></article></section><section class="wpf-recent"><h2>Recent modules</h2><button v-for="module in modules.modules" :key="module.id" @click="$router.push('/modules');modules.selectedModuleId=module.id"><span class="module-icon">{{module.displayName.slice(0,1).toUpperCase()}}</span><span><strong>{{module.displayName}}</strong><small>{{module.displayDescription}}</small></span><em>{{module.runtimeState}}</em></button></section><section class="wpf-home-actions"><RouterLink to="/modules"><b>▦</b><span>View modules</span></RouterLink><button @click="refresh"><b>↻</b><span>Refresh modules</span></button></section></template></QPage></template>
